// ---------- zinnen met namen of getallen ----------
const N = "([\\d.,]+)";
// onderdelen van "Deze route gaat via …" (ruimer gezochte route)
const DIFF_T = {groene:["green","grüne","verte","verde"], blauwe:["blue","blaue","bleue","blu"], rode:["red","rote","rouge","rossa"], zwarte:["black","schwarze","noire","nera"], dubbelzwarte:["double black","doppelschwarze","double noire","doppia nera"], ongemarkeerde:["unmarked","unmarkierte","non balisée","non segnata"]};
function viaT(s, l){
  return s.split(" en ").map(b => { let m;
    if((m = b.match(/^één skiroute boven je niveau$/))) return ["one ski route above your level", "eine Skiroute über deinem Niveau", "un itinéraire au-dessus de ton niveau", "un itinerario sopra il tuo livello"][l];
    if((m = b.match(/^één (\S+) piste boven je niveau$/))) return [`one ${DIFF_T[m[1]]?.[0] || m[1]} run above your level`, `eine ${DIFF_T[m[1]]?.[1] || m[1]} Piste über deinem Niveau`,
      `une piste ${DIFF_T[m[1]]?.[2] || m[1]} au-dessus de ton niveau`, `una pista ${DIFF_T[m[1]]?.[3] || m[1]} sopra il tuo livello`][l];
    if((m = b.match(/^(\d+) pistes boven je niveau$/))) return [`${m[1]} runs above your level`, `${m[1]} Pisten über deinem Niveau`, `${m[1]} pistes au-dessus de ton niveau`, `${m[1]} piste sopra il tuo livello`][l];
    if(b === "één keer met de lift naar beneden") return ["riding a lift down once", "einmal mit dem Lift nach unten", "une descente en remontée", "una discesa in impianto"][l];
    if((m = b.match(/^(\d+) keer met de lift naar beneden$/))) return [`riding a lift down ${m[1]} times`, `${m[1]}-mal mit dem Lift nach unten`, `${m[1]} descentes en remontée`, `${m[1]} discese in impianto`][l];
    if((m = b.match(/^(.+) lopen$/))) return [`walking ${m[1]}`, `${m[1]} zu Fuß`, `${m[1]} à pied`, `${m[1]} a piedi`][l];
    return b;
  }).join([" and ", " und ", " et ", " e "][l]);
}
